# Matura z historii, czerwiec 2024 (termin dodatkowy) — omówienie IndexLab.
# CKE nie publikuje arkuszy z terminu dodatkowego na swojej stronie, dlatego zamiast linku
# każda wiązka ma autorski opis materiałów źródłowych (bez przepisywania źródeł CKE).

def WM(nr, tytul, dzial, material, *zadania):
    w = W(nr, 0, tytul, dzial, *zadania)
    w['material'] = material
    w['uwaga'] = 'Opis materiału źródłowego przygotowany przez IndexLab — oryginalny arkusz CKE z terminu dodatkowego nie jest publikowany na stronie CKE.'
    return w


